import android.os.Handler;
import android.os.Looper;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.Callable;
import java.util.concurrent.atomic.AtomicReference;
import com.joaomgcd.taskerm.action.java.ClassImplementation;
import com.joaomgcd.taskerm.action.java.JavaCodeException;

/* Wait for Android's actual completion/cancellation, not merely acceptance. */
performStroke(service, stroke, phase) {
    signal = new CountDownLatch(1);
    result = new AtomicReference("timeout");
    callback = tasker.implementClass(AccessibilityService.GestureResultCallback.class,
        new ClassImplementation() {
            run(Callable superCaller, String methodName, Object[] args) {
                if (methodName.equals("onCompleted")) {
                    result.set("completed");
                    signal.countDown();
                    return null;
                }
                if (methodName.equals("onCancelled")) {
                    result.set("cancelled");
                    signal.countDown();
                    return null;
                }
                return superCaller.call();
            }
        });
    tasker.setVariable("SIG3_TouchStage", phase);
    gesture = new GestureDescription.Builder().addStroke(stroke).build();
    if (!service.dispatchGesture(gesture, callback, new Handler(Looper.getMainLooper())))
        throw new JavaCodeException(phase + ": dispatchGesture rejected");
    if (!signal.await(3, TimeUnit.SECONDS))
        throw new JavaCodeException(phase + ": completion timed out after 3000 ms");
    if (!result.get().equals("completed"))
        throw new JavaCodeException(phase + ": Android cancelled gesture");
}

if (Build.VERSION.SDK_INT < 26)
    throw new JavaCodeException("Continuous touch requires Android 8 or later");
service = tasker.getAccessibilityService();
if (service == null)
    throw new JavaCodeException("Enable Tasker in Android Settings > Accessibility > Installed apps");
x = Float.parseFloat(tasker.getVariable("sig3_x"));
y = Float.parseFloat(tasker.getVariable("sig3_y"));
endY = Float.parseFloat(tasker.getVariable("sig3_end_y"));
if (x < 0 || endY < 0 || Math.abs(y - endY) < 1 || Math.abs(y - endY) > 200)
    throw new JavaCodeException("Invalid calibrated step coordinates");
metrics = service.getResources().getDisplayMetrics();
if (x >= metrics.widthPixels || y < 0 || y >= metrics.heightPixels || endY >= metrics.heightPixels)
    throw new JavaCodeException("Gesture coordinates outside display bounds");
holdPath = new Path();
holdPath.moveTo(x, y);
/* willContinue=true keeps this pointer DOWN after the stationary 200 ms. */
holdStroke = new GestureDescription.StrokeDescription(holdPath, 0, 200, true);
movePath = new Path();
movePath.moveTo(x, y);
movePath.lineTo(x, endY);
/* Continue the SAME pointer; false releases it at the end of the 300 ms MOVE. */
moveStroke = holdStroke.continueStroke(movePath, 0, 300, false);
held = false;
try {
    held = true;
    performStroke(service, holdStroke, "down-hold");
    performStroke(service, moveStroke, "move");
    held = false;
    tasker.setVariable("SIG3_TouchStage", "released");
} finally {
    if (held) {
        /* Best-effort release of a held pointer after rejection/timeout/error. */
        try {
            releaseStroke = holdStroke.continueStroke(holdPath, 0, 1, false);
            service.dispatchGesture(new GestureDescription.Builder().addStroke(releaseStroke).build(), null, null);
        } catch (Exception releaseError) {
            tasker.log("SIG3 held-pointer cleanup: " + releaseError.toString());
        }
    }
}
return "completed";

/* Read-only preflight: no volume, route, DND or lock settings are changed. */
import android.app.KeyguardManager;
import android.app.NotificationManager;
import android.media.AudioManager;
import android.media.AudioDeviceInfo;
import android.os.PowerManager;
import android.os.Build;
import com.joaomgcd.taskerm.action.java.JavaCodeException;
pm = context.getSystemService("power");
km = context.getSystemService("keyguard");
if (!pm.isInteractive() || km.isKeyguardLocked())
    throw new JavaCodeException("Turn on and unlock the phone before controlling Signia");
am = context.getSystemService("audio");
nm = context.getSystemService("notification");
streamName = tasker.getVariable("SIG3_AudioStream");
if (!"media".equals(streamName) && !"ring".equals(streamName))
    throw new JavaCodeException("Set SIG3_AudioStream to Signia's selected media or ring stream");
stream = "ring".equals(streamName) ? AudioManager.STREAM_RING : AudioManager.STREAM_MUSIC;
volume = am.getStreamVolume(stream);
maximum = am.getStreamMaxVolume(stream);
mode = am.getMode();
filter = nm.getCurrentInterruptionFilter();
outputs = am.getDevices(AudioManager.GET_DEVICES_OUTPUTS);
route = "";
external = false;
for (device : outputs) {
    type = device.getType();
    route = route + type + ":" + device.getProductName() + ";";
    /* Known connected external outputs; presence is conservative, not an active-route claim. */
    if (type == 3 || type == 4 || type == 7 || type == 8 || type == 11 || type == 12 || type == 22 || type == 23 || type == 26 || type == 27)
        external = true;
}
tasker.setVariable("SIG3_AudioDiagnostics", "stream=" + streamName + " volume=" + volume + "/" + maximum + "; mode=" + mode + "; interruptionFilter=" + filter + "; outputs=" + route);
if (volume == 0) throw new JavaCodeException("Selected phone audio stream is muted");
if (mode == AudioManager.MODE_IN_CALL || mode == AudioManager.MODE_IN_COMMUNICATION)
    throw new JavaCodeException("Phone call or communication audio is active");
if (external) throw new JavaCodeException("Disconnect external audio outputs before acoustic control");
if ("ring".equals(streamName) && (am.getRingerMode() != AudioManager.RINGER_MODE_NORMAL || filter != NotificationManager.INTERRUPTION_FILTER_ALL))
    throw new JavaCodeException("Ringtone acoustic control is blocked by silent/DND state");
/* Media DND and Signia's configurable volume thresholds are recorded, not guessed. */
return "ready";

/* Program selection through visible accessibility nodes, never fixed coordinates. */
import android.view.accessibility.AccessibilityNodeInfo;
import com.joaomgcd.taskerm.action.java.JavaCodeException;
import android.os.SystemClock;
visibleNodes(root, id) {
    nodes = root.findAccessibilityNodeInfosByViewId(id);
    result = new java.util.ArrayList();
    for (node : nodes) if (node.isVisibleToUser() && node.isEnabled()) result.add(node);
    return result;
}
clickNode(node) {
    for (int depth = 0; depth < 5 && node != null; depth++) {
        if (node.isClickable()) {
            if (!node.performAction(AccessibilityNodeInfo.ACTION_CLICK)) throw new JavaCodeException("Accessibility click rejected");
            return;
        }
        node = node.getParent();
    }
    throw new JavaCodeException("No clickable ancestor for selected node");
}
readProgram(service, id) {
    root = service.getRootInActiveWindow();
    if (root == null || root.getPackageName() == null || !"com.signia.rta".contentEquals(root.getPackageName())) throw new JavaCodeException("Signia is not foreground");
    nodes = visibleNodes(root, id);
    if (nodes.size() != 1) throw new JavaCodeException("Current program is ambiguous; configure SIG3_ProgramId");
    value = nodes.get(0).getText();
    if (value == null || value.toString().trim().length() == 0) throw new JavaCodeException("Current program has no readable text");
    return value.toString().trim();
}
service = tasker.getAccessibilityService();
if (service == null) throw new JavaCodeException("Enable Tasker accessibility");
requested = tasker.getVariable("par1");
if (requested == null || !requested.matches("[1-6]")) throw new JavaCodeException("Program slot must be 1–6");
target = tasker.getVariable("SIG3_ProgramName" + requested);
if (target == null || target.trim().length() == 0) throw new JavaCodeException("Configure SIG3_ProgramName" + requested + " from the actual program list");
id = tasker.getVariable("SIG3_ProgramId");
previous = readProgram(service, id);
tasker.setVariable("SIG3_Previous", previous);
tasker.setVariable("SIG3_Expected", target);
if (!previous.equals(target)) {
    root = service.getRootInActiveWindow();
    open = visibleNodes(root, tasker.getVariable("SIG3_ProgramOpenId"));
    if (open.size() != 1) throw new JavaCodeException("Program opener missing/ambiguous; configure SIG3_ProgramOpenId");
    clickNode(open.get(0));
    selected = false;
    for (int attempt = 0; attempt < 20 && !selected; attempt++) {
        SystemClock.sleep(150);
        root = service.getRootInActiveWindow();
        if (root == null || root.getPackageName() == null || !"com.signia.rta".contentEquals(root.getPackageName())) throw new JavaCodeException("Program chooser not in Signia");
        candidates = root.findAccessibilityNodeInfosByText(target);
        exact = new java.util.ArrayList();
        for (node : candidates) if (node.isVisibleToUser() && node.isEnabled() && node.getText() != null && target.equals(node.getText().toString().trim())) exact.add(node);
        if (exact.size() > 1) throw new JavaCodeException("Program name matches multiple visible items");
        if (exact.size() == 1) { clickNode(exact.get(0)); selected = true; }
    }
    if (!selected) throw new JavaCodeException("Configured program not found");
}
for (int attempt = 0; attempt < 20; attempt++) {
    SystemClock.sleep(150);
    try {
        observed = readProgram(service, id);
        tasker.setVariable("SIG3_Observed", observed);
        if (target.equals(observed)) {
            tasker.setVariable("SIG3_Program", observed);
            return "displayed";
        }
    } catch (JavaCodeException unavailable) { }
}
throw new JavaCodeException("Program did not become the configured target; inspect Signia before retrying");

